INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'alphabet-a-m', 'A0', 'The Alphabet A–M', 'Das Alphabet A–M', 'foundation', 'Say the first half of the German alphabet and spell your name out loud.', 1) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wie schreibt man das?', '{"title":"Wie schreibt man das?","lines":[{"speaker":"Beamtin","de":"Wie heißen Sie, bitte?","en":"What is your name, please?"},{"speaker":"Herr Baum","de":"Ich heiße Baum. B wie Berta, A, U, M.","en":"My name is Baum. B as in Berta, A, U, M."},{"speaker":"Beamtin","de":"Buchstabieren Sie bitte Ihren Vornamen.","en":"Please spell your first name."},{"speaker":"Herr Baum","de":"J-A-K-O-B. Jakob.","en":"J-A-K-O-B. Jakob."}],"question":"What is the man asked to do?","options":["Spell his first name","Repeat his address","Show his passport"],"answer":0}'::jsonb, 'buchstabieren means to spell. Germans often say B wie Berta to make a letter clear.', 100) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Die ersten Buchstaben', '{"title":"Die ersten Buchstaben","text_de":"Das deutsche Alphabet hat sechsundzwanzig Buchstaben. A, B, C, D, E, F, G, H, I, J, K, L und M sind die ersten dreizehn. Das J spricht man wie das englische y, und das C hört man meistens nur in Kombinationen wie ch.","text_en":"The German alphabet has twenty-six letters. A, B, C, D, E, F, G, H, I, J, K, L and M are the first thirteen. J sounds like the English y, and C is mostly heard only in combinations such as ch.","question":"How many letters does the German alphabet have?","options":["Twenty-four","Twenty-six","Thirty"],"answer":1}'::jsonb, 'Letter names differ from English: E sounds like ay, I sounds like ee.', 101) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"A, B, C, D, E, F, G","en":"A, B, C, D, E, F, G","stress":"AH BEH TSEH DEH EH EFF GEH","tip":"C is tseh and G is geh with a hard g, never a j sound."}'::jsonb, 'Stress pattern: AH BEH TSEH DEH EH EFF GEH', 102) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Wie ___ man das?","en":"How do you spell that?","options":["schreibt","spricht","liest"],"answer":0}'::jsonb, 'Wie schreibt man das? is the standard way to ask for a spelling.', 103) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Können","Sie","das","bitte","buchstabieren"],"answer":["Können","Sie","das","bitte","buchstabieren"],"en":"Could you spell that, please?"}'::jsonb, 'In a question the verb comes first and the infinitive goes to the end.', 104) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"A","en":"ah"},{"de":"B","en":"beh"},{"de":"C","en":"tseh"},{"de":"D","en":"deh"},{"de":"E","en":"eh"},{"de":"F","en":"eff"},{"de":"G","en":"geh"},{"de":"H","en":"hah"},{"de":"I","en":"ee"},{"de":"J","en":"yot"},{"de":"K","en":"kah"},{"de":"L","en":"ell"},{"de":"M","en":"emm"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 105) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Der Buchstabe J klingt wie das englische ___.","en":"The letter J sounds like the English y.","options":["j","y","g"],"answer":1}'::jsonb, 'German J = English y, as in ja and Jakob.', 106) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"Someone says a name too quickly on the phone.","question":"What do you say?","options":["Was?","Können Sie das bitte buchstabieren?","Sprechen Sie lauter!"],"answer":1}'::jsonb, 'Asking politely for a spelling is the normal move on the phone.', 107) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('7e2e8f53-e324-596a-af2b-711c97871959'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Buchstabieren Sie Ihren Namen auf Deutsch.', '{"prompt":"Buchstabieren Sie Ihren Namen auf Deutsch.","hint":"Use: Ich heiße …, Das schreibt man …","sample":"Ich heiße Anna. Das schreibt man A-N-N-A. Mein Nachname ist Klein: K-L-E-I-N."}'::jsonb, 'Use the hint and compare your answer with the model.', 108) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'alphabet-n-z', 'A0', 'The Alphabet N–Z & Umlauts', 'Das Alphabet N–Z & Umlaute', 'foundation', 'Finish the alphabet and meet Ä, Ö, Ü and ß.', 2) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Am Telefon', '{"title":"Am Telefon","lines":[{"speaker":"Mitarbeiter","de":"Und Ihr Nachname?","en":"And your surname?"},{"speaker":"Frau Groß","de":"Groß. G-R-O-ß, das scharfe S.","en":"Groß. G-R-O-ß, the sharp S."},{"speaker":"Mitarbeiter","de":"Mit Eszett, alles klar. Und die Straße?","en":"With eszett, understood. And the street?"},{"speaker":"Frau Groß","de":"Königsweg, mit Ö.","en":"Königsweg, with Ö."}],"question":"Which special letter is in her surname?","options":["Ü","ß","Ä"],"answer":1}'::jsonb, 'ß is called Eszett or scharfes S and is always pronounced like a sharp s.', 200) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Der Rest des Alphabets', '{"title":"Der Rest des Alphabets","text_de":"Nach dem M kommen N, O, P, Q, R, S, T, U, V, W, X, Y und Z. Dazu gibt es vier Sonderzeichen: Ä, Ö, Ü und ß. Das V klingt wie f, das W wie ein englisches v und das Z wie ts.","text_en":"After M come N, O, P, Q, R, S, T, U, V, W, X, Y and Z. There are also four special characters: Ä, Ö, Ü and ß. V sounds like f, W like an English v and Z like ts.","question":"How does the German W sound?","options":["Like English w","Like English v","Like f"],"answer":1}'::jsonb, 'V and W swap places compared with English: Vater = fahter, Wasser = vasser.', 201) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"V, W, X, Y, Z","en":"V, W, X, Y, Z","stress":"fau VEH ix IPP-si-lon TSETT","tip":"Z is always tsett, never a buzzing z."}'::jsonb, 'Stress pattern: fau VEH ix IPP-si-lon TSETT', 202) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Mein Name ist Müller, mit ___.","en":"My name is Müller, with ü.","options":["ü","u","ue"],"answer":0}'::jsonb, 'Umlauts change the sound: u is oo, ü is a rounded ee.', 203) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Mein","Name","ist","Müller","mit","Umlaut"],"answer":["Mein","Name","ist","Müller","mit","Umlaut"],"en":"My name is Müller, with an umlaut."}'::jsonb, 'mit Umlaut is the quick way to clarify the spelling.', 204) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"N","en":"enn"},{"de":"O","en":"oh"},{"de":"P","en":"peh"},{"de":"Q","en":"kuh"},{"de":"R","en":"err"},{"de":"S","en":"ess"},{"de":"T","en":"teh"},{"de":"U","en":"oo"},{"de":"V","en":"fau"},{"de":"W","en":"veh"},{"de":"X","en":"ix"},{"de":"Y","en":"ypsilon"},{"de":"Z","en":"tsett"},{"de":"Ä","en":"ah-umlaut"},{"de":"Ö","en":"oh-umlaut"},{"de":"Ü","en":"oo-umlaut"},{"de":"ß","en":"eszett"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 205) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Das Wort Straße schreibt man mit ___.","en":"The word Straße is written with ß.","options":["ss","ß","s"],"answer":1}'::jsonb, 'ß follows long vowels; ss follows short ones (Straße vs. Fluss).', 206) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A clerk writes your name without the umlaut.","question":"How do you correct it politely?","options":["Falsch!","Entschuldigung, das ist mit Umlaut: ü.","Nochmal schreiben."],"answer":1}'::jsonb, 'Start with Entschuldigung and give the exact letter.', 207) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('aa7843fc-ac93-5621-af15-5be9903034e0'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Schreiben Sie drei Wörter mit Ä, Ö oder Ü.', '{"prompt":"Schreiben Sie drei Wörter mit Ä, Ö oder Ü.","hint":"Use: Das Wort … schreibt man mit …","sample":"Das Wort Käse schreibt man mit ä. Der Löffel hat ein ö. Die Tür schreibt man mit ü."}'::jsonb, 'Use the hint and compare your answer with the model.', 208) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'sounds-and-spelling', 'A0', 'Sounds & Spelling Rules', 'Laute & Rechtschreibung', 'foundation', 'Learn the letter combinations that make German easy to read aloud.', 3) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wie spricht man das?', '{"title":"Wie spricht man das?","lines":[{"speaker":"Lernerin","de":"Wie spricht man ie und ei?","en":"How do you pronounce ie and ei?"},{"speaker":"Lehrer","de":"Sie sprechen den zweiten Buchstaben: ie ist ii, ei ist ai.","en":"You say the second letter: ie is ee, ei is eye."},{"speaker":"Lernerin","de":"Also heißt wie ''vee'' und mein ''main''?","en":"So wie is ''vee'' and mein is ''mine''?"},{"speaker":"Lehrer","de":"Genau, sehr gut!","en":"Exactly, very good!"}],"question":"How is the combination ei pronounced?","options":["Like ee","Like eye","Like ay"],"answer":1}'::jsonb, 'Say the name of the second vowel: ei = eye, ie = ee.', 300) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Fünf Regeln', '{"title":"Fünf Regeln","text_de":"Sch klingt wie sh in Schule. Ch nach a, o, u ist rau wie in Buch. St und sp am Wortanfang klingen wie scht und schp: Straße, sprechen. Das r hinten im Hals ist typisch deutsch, und ein e am Wortende bleibt immer hörbar.","text_en":"Sch sounds like sh in Schule. Ch after a, o, u is rough as in Buch. St and sp at the start of a word sound like sht and shp: Straße, sprechen. The r comes from the back of the throat, and a final e is always audible.","question":"How does sp sound at the start of a word?","options":["Like sp in English","Like shp","Like ts"],"answer":1}'::jsonb, 'Word-initial st and sp always get the sh sound.', 301) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich spreche schon ein bisschen Deutsch.","en":"I already speak a little German.","stress":"ich SHPRE-che shohn ain BISS-chen DOITCH","tip":"spreche starts with shp; the ch in ich is soft, like a whispered h."}'::jsonb, 'Stress pattern: ich SHPRE-che shohn ain BISS-chen DOITCH', 302) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Das Wort Schule beginnt mit dem Laut ___.","en":"The word Schule begins with the sh sound.","options":["s","sch","ch"],"answer":1}'::jsonb, 'sch is one single sound, like English sh.', 303) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","spreche","langsam","und","deutlich"],"answer":["Ich","spreche","langsam","und","deutlich"],"en":"I speak slowly and clearly."}'::jsonb, 'The conjugated verb sits in position two in a German statement.', 304) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"sch","en":"sh sound"},{"de":"ch (nach a, o, u)","en":"rough h from the throat"},{"de":"ei","en":"sounds like eye"},{"de":"ie","en":"sounds like ee"},{"de":"eu","en":"sounds like oy"},{"de":"z","en":"sounds like ts"},{"de":"v","en":"sounds like f"},{"de":"w","en":"sounds like v"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 305) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"In dem Wort ''sie'' spricht man das ie wie ___.","en":"In the word sie the ie is pronounced like ee.","options":["ee","eye","ay"],"answer":0}'::jsonb, 'ie is a long ee: sie, wie, Liebe.', 306) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are unsure how to pronounce a word you just read.","question":"What do you ask?","options":["Sag das!","Wie spricht man das aus?","Ich verstehe nicht."],"answer":1}'::jsonb, 'Wie spricht man das aus? asks specifically about pronunciation.', 307) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('c4d1a219-2588-594d-a67e-545e429be63e'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Nennen Sie drei Wörter mit sch, ch oder ei.', '{"prompt":"Nennen Sie drei Wörter mit sch, ch oder ei.","hint":"Use: Das Wort … hat …","sample":"Das Wort Schwester hat sch. Das Wort Nacht hat ch. Das Wort Wein hat ei."}'::jsonb, 'Use the hint and compare your answer with the model.', 308) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'numbers-0-20', 'A0', 'Numbers 0–20', 'Zahlen 0–20', 'foundation', 'Count from zero to twenty and give your phone number.', 4) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Die Telefonnummer', '{"title":"Die Telefonnummer","lines":[{"speaker":"Arzthelferin","de":"Wie ist Ihre Telefonnummer?","en":"What is your phone number?"},{"speaker":"Patient","de":"Null, eins, sieben, drei, vier, zwölf.","en":"Zero, one, seven, three, four, twelve."},{"speaker":"Arzthelferin","de":"Und wie alt sind Sie?","en":"And how old are you?"},{"speaker":"Patient","de":"Ich bin neunzehn.","en":"I am nineteen."}],"question":"How old is the patient?","options":["Nine","Nineteen","Twelve"],"answer":1}'::jsonb, 'Germans often say zwo instead of zwei on the phone so it is not confused with drei.', 400) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Von null bis zwanzig', '{"title":"Von null bis zwanzig","text_de":"null, eins, zwei, drei, vier, fünf, sechs, sieben, acht, neun, zehn. Danach: elf, zwölf, dreizehn, vierzehn, fünfzehn, sechzehn, siebzehn, achtzehn, neunzehn, zwanzig. Achtung: sechzehn und siebzehn verlieren einen Laut.","text_en":"zero, one, two, three, four, five, six, seven, eight, nine, ten. Then: eleven, twelve, thirteen, fourteen, fifteen, sixteen, seventeen, eighteen, nineteen, twenty. Careful: sechzehn and siebzehn drop a sound.","question":"Which number is irregular?","options":["vierzehn","sechzehn","achtzehn"],"answer":1}'::jsonb, 'sechs becomes sech- and sieben becomes sieb- before -zehn.', 401) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"eins, zwei, drei, vier, fünf","en":"one, two, three, four, five","stress":"AINS TSVAI DRAI FEER FUENF","tip":"zwei starts with ts; fünf uses the rounded ü sound."}'::jsonb, 'Stress pattern: AINS TSVAI DRAI FEER FUENF', 402) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Nach zehn kommt ___.","en":"After ten comes eleven.","options":["elf","zwölf","zehnein"],"answer":0}'::jsonb, 'elf and zwölf are unique words, not built from zehn.', 403) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","bin","zwanzig","Jahre","alt"],"answer":["Ich","bin","zwanzig","Jahre","alt"],"en":"I am twenty years old."}'::jsonb, 'German says Jahre alt, literally years old.', 404) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"null","en":"0"},{"de":"eins","en":"1"},{"de":"zwei","en":"2"},{"de":"drei","en":"3"},{"de":"vier","en":"4"},{"de":"fünf","en":"5"},{"de":"sechs","en":"6"},{"de":"sieben","en":"7"},{"de":"acht","en":"8"},{"de":"neun","en":"9"},{"de":"zehn","en":"10"},{"de":"elf","en":"11"},{"de":"zwölf","en":"12"},{"de":"dreizehn","en":"13"},{"de":"vierzehn","en":"14"},{"de":"fünfzehn","en":"15"},{"de":"sechzehn","en":"16"},{"de":"siebzehn","en":"17"},{"de":"achtzehn","en":"18"},{"de":"neunzehn","en":"19"},{"de":"zwanzig","en":"20"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 405) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich bin ___ Jahre alt. (16)","en":"I am sixteen years old.","options":["sechszehn","sechzehn","sechsehn"],"answer":1}'::jsonb, 'sechzehn loses the s of sechs.', 406) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"Someone gives a phone number too fast to write down.","question":"What do you say?","options":["Stopp!","Langsamer bitte, noch einmal.","Egal."],"answer":1}'::jsonb, 'Langsamer bitte is polite and clear.', 407) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ecded57b-c829-50c1-a775-459e56fdcfa1'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Schreiben Sie Ihre Telefonnummer in Worten.', '{"prompt":"Schreiben Sie Ihre Telefonnummer in Worten.","hint":"Use: Meine Nummer ist … / Ich bin … Jahre alt.","sample":"Meine Nummer ist null eins sieben drei acht zwei. Ich bin achtzehn Jahre alt."}'::jsonb, 'Use the hint and compare your answer with the model.', 408) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'numbers-to-100', 'A0', 'Tens & Numbers to 100', 'Zehnerzahlen bis 100', 'foundation', 'Count in tens to one hundred and build every number in between.', 5) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wie viel kostet das?', '{"title":"Wie viel kostet das?","lines":[{"speaker":"Verkäufer","de":"Der Rucksack kostet vierzig Euro.","en":"The backpack costs forty euros."},{"speaker":"Kundin","de":"Und die Tasche?","en":"And the bag?"},{"speaker":"Verkäufer","de":"Fünfundsechzig Euro.","en":"Sixty-five euros."},{"speaker":"Kundin","de":"Dann nehme ich den Rucksack.","en":"Then I will take the backpack."}],"question":"How much is the bag?","options":["45","65","56"],"answer":1}'::jsonb, 'fünfundsechzig = five and sixty. German says the units first.', 500) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Die Zehner', '{"title":"Die Zehner","text_de":"zehn, zwanzig, dreißig, vierzig, fünfzig, sechzig, siebzig, achtzig, neunzig, hundert. Zwischen den Zehnern zählt man rückwärts: einundzwanzig, zweiunddreißig, siebenundvierzig. Dreißig schreibt man mit ß, und sechzig und siebzig sind wieder kürzer.","text_en":"ten, twenty, thirty, forty, fifty, sixty, seventy, eighty, ninety, one hundred. Between the tens you count backwards: twenty-one, thirty-two, forty-seven. dreißig is written with ß, and sechzig and siebzig are shortened again.","question":"How do you say 47 in German?","options":["vierzigsieben","siebenundvierzig","vierundsiebzig"],"answer":1}'::jsonb, 'Unit + und + ten, written as one word.', 501) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"zwanzig, dreißig, vierzig, fünfzig, hundert","en":"twenty, thirty, forty, fifty, one hundred","stress":"TSVAN-tsich DRAI-sich FEER-tsich FUENF-tsich HUN-dert","tip":"The ending -zig sounds like -tsich in most of Germany."}'::jsonb, 'Stress pattern: TSVAN-tsich DRAI-sich FEER-tsich FUENF-tsich HUN-dert', 502) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"83 heißt auf Deutsch ___.","en":"83 in German is dreiundachtzig.","options":["achtzigdrei","dreiundachtzig","achtunddreizig"],"answer":1}'::jsonb, 'Units first: drei + und + achtzig.', 503) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Das","kostet","fünfundsiebzig","Euro"],"answer":["Das","kostet","fünfundsiebzig","Euro"],"en":"That costs seventy-five euros."}'::jsonb, 'Prices follow the verb: Das kostet + amount + Euro.', 504) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"zehn","en":"10"},{"de":"zwanzig","en":"20"},{"de":"dreißig","en":"30"},{"de":"vierzig","en":"40"},{"de":"fünfzig","en":"50"},{"de":"sechzig","en":"60"},{"de":"siebzig","en":"70"},{"de":"achtzig","en":"80"},{"de":"neunzig","en":"90"},{"de":"hundert","en":"100"},{"de":"einundzwanzig","en":"21"},{"de":"zweiunddreißig","en":"32"},{"de":"siebenundvierzig","en":"47"},{"de":"neunundneunzig","en":"99"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 505) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"30 schreibt man ___.","en":"30 is written dreißig.","options":["dreizig","dreißig","dreiszig"],"answer":1}'::jsonb, 'dreißig is the only ten with ß instead of z.', 506) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You want to check a price you think you misheard.","question":"What do you ask?","options":["Wie bitte, fünfzig oder fünfzehn?","Zu teuer!","Sagen Sie das nochmal."],"answer":0}'::jsonb, 'Naming both options is the clearest way to resolve 15 vs 50.', 507) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('5f893753-420f-5401-ab0c-27247b49e3c7'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Schreiben Sie drei Preise in Worten.', '{"prompt":"Schreiben Sie drei Preise in Worten.","hint":"Use: Das kostet … Euro.","sample":"Das Buch kostet zwölf Euro. Die Jacke kostet fünfundvierzig Euro. Das Fahrrad kostet hundert Euro."}'::jsonb, 'Use the hint and compare your answer with the model.', 508) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'grammar-basics', 'A0', 'Basic Grammar Rules', 'Grammatik-Grundlagen', 'foundation', 'The three articles, verb endings, pronouns and the verb-second rule.', 6) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Der, die oder das?', '{"title":"Der, die oder das?","lines":[{"speaker":"Lernerin","de":"Warum heißt es der Tisch, aber die Lampe?","en":"Why is it der Tisch but die Lampe?"},{"speaker":"Lehrer","de":"Jedes Nomen hat ein Geschlecht: der, die oder das.","en":"Every noun has a gender: der, die or das."},{"speaker":"Lernerin","de":"Und wie lerne ich das?","en":"And how do I learn that?"},{"speaker":"Lehrer","de":"Lernen Sie das Wort immer mit dem Artikel.","en":"Always learn the word together with its article."}],"question":"What advice does the teacher give?","options":["Learn nouns with their article","Ignore the gender","Only use das"],"answer":0}'::jsonb, 'Nouns are always capitalised and always carry a gender.', 600) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Vier Grundregeln', '{"title":"Vier Grundregeln","text_de":"Erstens: Nomen schreibt man groß und sie haben der, die oder das. Zweitens: Das Verb steht im Aussagesatz an Position zwei. Drittens: Verben bekommen Endungen — ich lerne, du lernst, er lernt, wir lernen, ihr lernt, sie lernen. Viertens: Für höfliche Anrede benutzt man Sie.","text_en":"First: nouns are capitalised and take der, die or das. Second: the verb stands in position two in a statement. Third: verbs take endings — ich lerne, du lernst, er lernt, wir lernen, ihr lernt, sie lernen. Fourth: use Sie for polite address.","question":"Where does the verb go in a German statement?","options":["At the end","In second position","First"],"answer":1}'::jsonb, 'Verb-second is the backbone of German word order.', 601) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Der Tisch, die Lampe, das Fenster.","en":"The table, the lamp, the window.","stress":"der TISH dee LAM-pe das FEN-ster","tip":"Keep the article unstressed and stress the noun."}'::jsonb, 'Stress pattern: der TISH dee LAM-pe das FEN-ster', 602) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ Kind spielt im Garten.","en":"The child is playing in the garden.","options":["Der","Die","Das"],"answer":2}'::jsonb, 'Kind is neuter: das Kind.', 603) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Heute","lerne","ich","Deutsch"],"answer":["Heute","lerne","ich","Deutsch"],"en":"Today I am learning German."}'::jsonb, 'When a time word comes first, the verb still stays in position two and the subject follows it.', 604) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der","en":"the (masculine)"},{"de":"die","en":"the (feminine / plural)"},{"de":"das","en":"the (neuter)"},{"de":"ich","en":"I"},{"de":"du","en":"you (informal)"},{"de":"er / sie / es","en":"he / she / it"},{"de":"wir","en":"we"},{"de":"ihr","en":"you (plural)"},{"de":"sie / Sie","en":"they / you (polite)"},{"de":"das Nomen","en":"the noun"},{"de":"das Verb","en":"the verb"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 605) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Du ___ sehr schnell.","en":"You learn very quickly.","options":["lerne","lernst","lernt"],"answer":1}'::jsonb, 'The du form ends in -st.', 606) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are speaking to an older stranger in a shop.","question":"Which form do you use?","options":["Wie heißt du?","Wie heißen Sie?","Wie heißt ihr?"],"answer":1}'::jsonb, 'Sie is the respectful form with strangers and in formal settings.', 607) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b010c81e-8ef9-5988-a748-c464d64e4c1b'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Schreiben Sie drei Sätze über sich mit dem Verb an Position zwei.', '{"prompt":"Schreiben Sie drei Sätze über sich mit dem Verb an Position zwei.","hint":"Use: Ich heiße …, Ich lerne …, Heute …","sample":"Ich heiße Sofia. Ich lerne seit einem Monat Deutsch. Heute übe ich das Alphabet und die Zahlen."}'::jsonb, 'Use the hint and compare your answer with the model.', 608) ON CONFLICT (id) DO NOTHING;
